class Solution:
    def minOperations(self, s: str) -> int:
        n = len(s)
        best = float('inf')
        for r in range(n):
            t = s[r:] + s[:r]
            c = r
            for i in range(n // 2):
                x = ord(t[i]) - 97
                y = ord(t[n - 1 - i]) - 97
                c += min((y - x) % 26, (x - y) % 26)
                if c >= best:
                    break
            best = min(best, c)
        return best

