class Solution {
public:
    int minOperations(string s) {
        int n = s.size();
        int best = INT_MAX;
        for (int r = 0; r < n; r++) {
            string t = s.substr(r) + s.substr(0, r);
            long long c = r;
            for (int i = 0; i < n / 2 && c < best; i++) {
                int x = t[i] - 'a', y = t[n - 1 - i] - 'a';
                int d = (y - x + 26) % 26;
                c += min(d, 26 - d);
            }
            best = min(best, (int)c);
        }
        return best;
    }
};

