class Solution {
    public int minOperations(String s) {
        int n = s.length();
        int best = Integer.MAX_VALUE;
        for (int r = 0; r < n; r++) {
            String t = s.substring(r) + s.substring(0, r);
            long c = r;
            for (int i = 0; i < n / 2 && c < best; i++) {
                int x = t.charAt(i) - 'a', y = t.charAt(n - 1 - i) - 'a';
                int d = (y - x + 26) % 26;
                c += Math.min(d, 26 - d);
            }
            best = (int) Math.min(best, c);
        }
        return best;
    }
}

