var minOperations = function(s) {
    const n = s.length;
    let best = Infinity;
    for (let r = 0; r < n; r++) {
        const t = s.slice(r) + s.slice(0, r);
        let c = r;
        for (let i = 0; i < (n >> 1) && c < best; i++) {
            const x = t.charCodeAt(i) - 97, y = t.charCodeAt(n - 1 - i) - 97;
            const d = (y - x + 26) % 26;
            c += Math.min(d, 26 - d);
        }
        best = Math.min(best, c);
    }
    return best;
};
